mapper.select:
select *
from d_order
where order_number = #{orderNumber,jdbcType=BIGINT}
  and user_id = #{userId,jdbcType=BIGINT}
  and status = 1
limit 1

mapper.update:
update d_order
set expiry_retry_count = COALESCE(expiry_retry_count, 0) + 1,
    expiry_next_retry_time = #{nextRetryTime,jdbcType=TIMESTAMP},
    expiry_last_error = #{lastError,jdbcType=VARCHAR},
    edit_time = #{now,jdbcType=TIMESTAMP}
where id = #{id,jdbcType=BIGINT}
  and order_status = 1
  and expire_time <= #{now,jdbcType=TIMESTAMP}
  and status = 1
